import React from "react";

interface ReportRow {
  id: string;
  name: string;
  startTimeUtc: string;
  endTimeUtc: string;
  venue: string;
  attendeeCount: number;
}

interface ReportViewerProps {
  reportJson: {
    reportGeneratedOn: string;
    data: ReportRow[];
  };
}

const ReportViewer: React.FC<ReportViewerProps> = ({ reportJson }) => {
  const rows = reportJson.data ?? [];

  return (
    <div>
      <div>
        Report Generated On:{" "}
        {reportJson.reportGeneratedOn
          ? new Date(reportJson.reportGeneratedOn).toLocaleString()
          : "N/A"}
      </div>

      {rows.length === 0 ? (
        <p>No report data available for the selected range.</p>
      ) : (
        <table>
          <thead>
            <tr>
              <th>Name</th>
              <th>Start</th>
              <th>End</th>
              <th>Venue</th>
              <th>#Attendees</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((r) => (
              <tr key={r.id}>
                <td>{r.name}</td>
                <td>{new Date(r.startTimeUtc).toLocaleString()}</td>
                <td>{new Date(r.endTimeUtc).toLocaleString()}</td>
                <td>{r.venue}</td>
                <td>{r.attendeeCount}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
};

export default ReportViewer;
